package org.pianoml.backend.entity;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import lombok.Data;

import java.time.LocalDate;
import java.time.OffsetDateTime;
import java.util.UUID;

/**
 * All the takes of a user on one score or exercise during one visit of the workbench (issue #399).
 * The id is generated by the client, which re-sends the whole session each time it changes.
 */
@Entity
@Table(name = "practice_session", schema = "pianoml")
@Data
public class PracticeSession {

  public static final String KIND_SCORE = "score";
  public static final String KIND_EXERCISE = "exercise";

  @Id
  private UUID id;

  @Column(name = "user_id", nullable = false)
  private UUID userId;

  @Column(nullable = false)
  private String kind;

  /** Null for an exercise, and for a score deleted since (title, author, key and grade are snapshots). */
  @Column(name = "score_id")
  private UUID scoreId;

  private String title;

  private String author;

  @Column(name = "exercise_type")
  private String exerciseType;

  @Column(name = "pattern_key")
  private String patternKey;

  @Column(name = "exercise_key")
  private String exerciseKey;

  private String tonic;

  private String mode;

  private Float grade;

  @Column(name = "started_at", nullable = false)
  private OffsetDateTime startedAt;

  @Column(name = "ended_at", nullable = false)
  private OffsetDateTime endedAt;

  /** Calendar day of startedAt in the user's time zone: the unit of streaks. */
  @Column(name = "local_date", nullable = false)
  private LocalDate localDate;

  @Column(name = "time_zone")
  private String timeZone;

  @Column(name = "active_seconds", nullable = false)
  private int activeSeconds;

  @Column(name = "take_count", nullable = false)
  private int takeCount;

  @Column(name = "completed_count", nullable = false)
  private int completedCount;

  @Column(name = "measure_start")
  private Integer measureStart;

  @Column(name = "measure_end")
  private Integer measureEnd;

  @Column(name = "measure_total")
  private Integer measureTotal;

  private String hands;

  @Column(name = "tempo_factor")
  private Double tempoFactor;

  private Boolean metronome;

  @Column(name = "is_loop")
  private Boolean loop;

  private String input;

  @Column(name = "notes_expected", nullable = false)
  private int notesExpected;

  @Column(name = "notes_hit", nullable = false)
  private int notesHit;

  @Column(name = "notes_wrong", nullable = false)
  private int notesWrong;

  @Column(nullable = false)
  private int onsets;

  @Column(nullable = false)
  private int waits;

  /** notesHit / (notesExpected + notesWrong); null when nothing was assessed. */
  private Double accuracy;

  /** 1 - waits / onsets; null when nothing was assessed. */
  private Double flow;

  @Column(name = "end_reason")
  private String endReason;

  /** JSON: {"measures": [...], "takes": [...]} (PracticeMeasure and PracticeTake of the API). */
  @Column(columnDefinition = "text")
  private String detail;
}
